{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Cohort-based wellness coaching combining small habits, soulful clarity, and measurable outcomes with {{COACH_NAME}}, {{CREDENTIALS}} in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="/index.html">
        <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" class="brand-avatar">
        <div class="brand-text">
          <strong>{{BUSINESS_NAME}}</strong>
          <small class="muted">{{TAGLINE}}</small>
        </div>
      </a>
      <nav class="nav" id="main-nav">
        <ul>
          <li><a href="/index.html">Home</a></li>
          <li><a href="/about.html">About</a></li>
          <li><a href="/programs.html">Work With Me</a></li>
          <li><a href="/services.html">Services</a></li>
          <li><a href="/pricing.html">Pricing</a></li>
          <li><a href="/testimonials.html">Stories</a></li>
          <li><a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
      <button class="nav-toggle" id="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1>Find clarity, steady rituals, and a sustainable rhythm for well-being.</h1>
          <p class="lead">Join a cohort-based path led by {{COACH_NAME}}, {{CREDENTIALS}} — a precise framework for lifelong habits without fad promises.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="#diagnostic">Take the quick assessment</a>
          </div>
          <ul class="hero-features">
            <li>8-week cohort format — guided, communal, sustainable</li>
            <li>Actionable micro-habits you can implement today</li>
            <li>Tools to measure progress gently and clearly</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Wellness illustration">
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section class="diagnostic" id="diagnostic">
      <div class="container">
        <div class="section-header">
          <h2>Quick Clarity Diagnostic</h2>
          <p class="muted">A three-minute reflective quiz to map where small change yields the biggest return.</p>
        </div>
        <form id="diagnostic-form" class="card grid-3">
          <div class="field">
            <label>Energy through the day</label>
            <select name="energy">
              <option value="low">Low — frequent dips</option>
              <option value="steady">Steady — manageable</option>
              <option value="high">High — consistent</option>
            </select>
          </div>
          <div class="field">
            <label>Sleep quality</label>
            <select name="sleep">
              <option value="restless">Restless</option>
              <option value="ok">Okay but improvable</option>
              <option value="rested">Rested</option>
            </select>
          </div>
          <div class="field">
            <label>Daily focus & calm</label>
            <select name="focus">
              <option value="scattered">Scattered</option>
              <option value="improving">Improving</option>
              <option value="centered">Centered</option>
            </select>
          </div>
          <div class="field full">
            <label>Primary intention for change</label>
            <input name="intention" placeholder="e.g., more energy, less anxiety, clearer appetite">
          </div>

          <div class="actions full">
            <button type="submit" class="btn primary">Get my short plan</button>
            <button type="button" class="btn ghost" id="reset-diagnostic">Reset</button>
          </div>

          <div id="diagnostic-result" class="result full" aria-live="polite" hidden>
            <!-- Filled by JS -->
          </div>
        </form>
      </div>
    </section>

    <!-- PLAN -->
    <section class="plan" id="plan">
      <div class="container">
        <div class="section-header">
          <h2>The Five-Fold Framework</h2>
          <p class="muted">A clinical, clear map that we use across cohorts. Each pillar is taught, practiced, and measured.</p>
        </div>
        <div class="grid-4 cards">
          <article class="card">
            <h3>1 — Baseline Mapping</h3>
            <p>Objective baseline to see what small changes matter most for you.</p>
          </article>
          <article class="card">
            <h3>2 — Ritual Design</h3>
            <p>Design daily micro-rituals that slot into your life without friction.</p>
          </article>
          <article class="card">
            <h3>3 — Environment Tuning</h3>
            <p>Shift cues and contexts so new habits stay effortless.</p>
          </article>
          <article class="card">
            <h3>4 — Community Accountability</h3>
            <p>Cohort support keeps momentum and transforms intention into practice.</p>
          </article>
          <article class="card">
            <h3>5 — Feedback Loop</h3>
            <p>Weekly simple metrics to refine what works and stop what doesn't.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section class="micro-habits" id="micro_habits">
      <div class="container">
        <div class="section-header">
          <h2>Micro Habits — Tiny Shifts, Big Momentum</h2>
          <p class="muted">Practical, bite-sized experiments you can start today.</p>
        </div>
        <div class="grid-3 habits">
          <div class="habit card">
            <h4>2-minute stillness</h4>
            <p>Morning centering to set intention for the day — breathe, name one priority.</p>
          </div>
          <div class="habit card">
            <h4>Protein-first plate</h4>
            <p>Start a meal with protein or fiber to stabilize energy and appetite.</p>
          </div>
          <div class="habit card">
            <h4>Micro-movement</h4>
            <p>60 seconds every hour to stand, stretch, and reset posture and focus.</p>
          </div>
          <div class="habit card">
            <h4>End-of-day review</h4>
            <p>60 seconds to mark one win and one gentle adjustment for tomorrow.</p>
          </div>
          <div class="habit card">
            <h4>One question check-in</h4>
            <p>Ask: "What felt nourishing today?" — then take one small next step.</p>
          </div>
          <div class="habit card">
            <h4>Hydration cue</h4>
            <p>Drink a glass of water before starting focused work blocks to clear fog.</p>
          </div>
        </div>
        <div class="micro-cta">
          <a class="btn primary" href="/programs.html">Explore cohort paths</a>
          <a class="btn ghost" href="/book.html">Schedule a discovery call</a>
        </div>
      </div>
    </section>

    <!-- PRICING -->
    <section class="pricing" id="pricing">
      <div class="container">
        <div class="section-header">
          <h2>Cohort Pricing & Enrollment</h2>
          <p class="muted">Transparent pricing for cohort experiences — limited seats to preserve quality.</p>
        </div>
        <div class="toggle-pricing">
          <label class="switch">
            <input id="billing-toggle" type="checkbox">
            <span class="slider"></span>
          </label>
          <small class="muted">Toggle for payment plan</small>
        </div>
        <div class="grid-3 plans">
          <div class="plan-card card">
            <h3>Discovery Cohort</h3>
            <p class="price"><span class="amount">$297</span> one-time</p>
            <ul>
              <li>4-week short cohort</li>
              <li>Weekly group session</li>
              <li>Micro-habit toolkit</li>
            </ul>
            <a class="btn primary enroll" href="/book.html">Reserve a seat</a>
          </div>
          <div class="plan-card card recommended">
            <h3>Transformation Cohort</h3>
            <p class="price"><span class="amount">$997</span> or 3x $350</p>
            <ul>
              <li>8-week flagship cohort (most popular)</li>
              <li>Weekly live training + office hours</li>
              <li>Personalized habit plan</li>
            </ul>
            <a class="btn primary enroll" href="{{PRIMARY_CTA_URL}}">Join the next cohort</a>
          </div>
          <div class="plan-card card">
            <h3>Sustain Cohort</h3>
            <p class="price"><span class="amount">$149/month</span></p>
            <ul>
              <li>Ongoing monthly group support</li>
              <li>Quarterly check-ins</li>
              <li>Access to resources library</li>
            </ul>
            <a class="btn ghost enroll" href="/pricing.html">Learn more</a>
          </div>
        </div>
        <p class="muted small">All cohorts emphasize outcomes, low-burden measurement, and cohort accountability rather than medical advice.</p>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="container cta-grid">
        <div>
          <h2>Ready to join a focused, soulful cohort?</h2>
          <p class="muted">Seats are intentionally limited to keep groups small and effective.</p>
        </div>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Questions? Contact us</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{TAGLINE}} • {{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p><a href="/privacy.html">Privacy</a> • <a href="/terms.html">Terms</a></p>
      </div>
    </div>
  </footer>
</body>
</html>"} 
